/// Ejercicios sinteticos para probar el armado de sesiones.
List<Exercise> testExercises() {
  return <Exercise>[
    _exercise('ex_a', ExerciseModule.identificacion, 1),
    _exercise('ex_b', ExerciseModule.identificacion, 3),
    _exercise('ex_c', ExerciseModule.identificacion, 2),
    _exercise('ex_d', ExerciseModule.clasificacion, 1),
    _exercise('ex_e', ExerciseModule.estructuras, 2),
  ];
}

Exercise _exercise(String id, ExerciseModule module, int difficulty) {
  return Exercise(
    id: id,
    module: module,
    competency: 'competencia_prueba',
    difficulty: difficulty,
    context: 'Contexto de prueba',
    stem: 'Enunciado $id',
    options: const <ExerciseOption>[
      ExerciseOption(id: 'a', text: 'Correcta', correct: true),
      ExerciseOption(id: 'b', text: 'Incorrecta', correct: false),
    ],
    explanation: 'Explicación $id',
    relatedIds: const <String>[],
  );
}
